inline bool newSession(){uint32_t old=MainIO::readSession();if(old==0xffffffffUL)old=0;if(old==0xfffffffeUL){fatal=true;MainIO::sayP(PSTR("ERROR session_exhausted\n"));return false;}session=old+1;counter=0;MainIO::persist(session);return true;}
