inline void processLine(){line[lineSize]=0;if(MainPolicy::exactStop(line,lineSize)){stop("priority_stop");}else if(!strcmp(line,"!status")){status();}else if(!strcmp(line,"!retry")){boot();}else if(!strcmp(line,"!trace")){MainIO::sayP(PSTR("STATUS trace=UART_STATUS_then_TWI_SPI actual_capture_required\n"));}else if(lineOverflow){stop("line_too_long");}else if(!ready){stop("not_ready");}else if(active||actorPending||MainLinks::bus[0].phase||MainLinks::bus[1].phase){stop("busy");}else{Intent::parse(line,lineSize,input);if(input.reason!=Intent::OK||input.guard){stop("input_rejected");}else{job=nextId();if(job){active=true;jobStarted=MainIO::now();scores.reset(job,generation);actorIssue(Proto::STATUS,job);for(uint8_t w=0;w<2;w++){workerStep[w]=2;workerRetry[w]=0;request(w,Proto::LOAD_INPUT,0);}}}}lineSize=0;lineOverflow=false;}
